"""==============================================================================IOTEC109_AGENT_MEMORY_ENGINE.py==============================================================================Memória Operacional dos Agentes=============================================================================="""from __future__ import annotationsimport sqlite3from pathlib import Pathfrom datetime import datetimeDATABASE = Path("iotec.db")class AgentMemory:    def __init__(self):        self.conn = sqlite3.connect(DATABASE)        self.conn.row_factory = sqlite3.Row        self.create_table()    # ==================================================================    def create_table(self):        self.conn.execute("""        CREATE TABLE IF NOT EXISTS agent_memory(            id INTEGER PRIMARY KEY AUTOINCREMENT,            created_at TEXT,            agent_uuid TEXT,            mission_uuid TEXT,            memory_key TEXT,            memory_value TEXT        )        """)        self.conn.commit()    # ==================================================================    def save(        self,        agent_uuid,        mission_uuid,        key,        value    ):        self.conn.execute("""        INSERT INTO agent_memory(            created_at,            agent_uuid,            mission_uuid,            memory_key,            memory_value        )        VALUES(?,?,?,?,?)        """,(            datetime.utcnow().isoformat(),            agent_uuid,            mission_uuid,            key,            value        ))        self.conn.commit()    # ==================================================================    def get(        self,        agent_uuid,        mission_uuid=None    ):        if mission_uuid:            rows = self.conn.execute("""                SELECT *                FROM agent_memory                WHERE                    agent_uuid=?                AND                    mission_uuid=?                ORDER BY id            """,(                agent_uuid,                mission_uuid            )).fetchall()        else:            rows = self.conn.execute("""                SELECT *                FROM agent_memory                WHERE                    agent_uuid=?                ORDER BY id            """,(                agent_uuid,            )).fetchall()        return [dict(r) for r in rows]    # ==================================================================    def last(self, agent_uuid):        row = self.conn.execute("""            SELECT *            FROM agent_memory            WHERE agent_uuid=?            ORDER BY id DESC            LIMIT 1        """,(agent_uuid,)).fetchone()        if row:            return dict(row)        return None    # ==================================================================    def clear(self, agent_uuid):        self.conn.execute("""            DELETE            FROM agent_memory            WHERE agent_uuid=?        """,(agent_uuid,))        self.conn.commit()# =============================================================================if __name__ == "__main__":    memory = AgentMemory()    memory.save(        "AG001",        "MISSION-001",        "CURRENT_MODULE",        "109_AGENT_MEMORY_ENGINE"    )    memory.save(        "AG001",        "MISSION-001",        "STATUS",        "RUNNING"    )    memory.save(        "AG002",        "MISSION-001",        "EXECUTION",        "OPENHANDS ONLINE"    )    print()    for item in memory.get("AG001"):        print(item)    print()    print(memory.last("AG002"))